import { Link, useHistory } from 'react-router-dom';
import { useContext, useState } from 'react';
import { StyleContext } from '../../context/StyleContextProvider';
import { CartContext } from '../../context/CartContext';
import Logo from '../../assets/LeSpotLogo.png';
import '../../styles/header.css';

function Header() {
    const { theme, setTheme } = useContext(StyleContext);
    const { cartItems, setCartItems } = useContext(CartContext); 
    const history = useHistory();
    const [isCartOpen, setIsCartOpen] = useState(false); // Gère l'ouverture du volet latéral

    const totalQuantity = cartItems.reduce((acc, item) => acc + (parseInt(item.quantity) || 0), 0);
    const totalPrice = cartItems.reduce((acc, item) => acc + item.price * (parseInt(item.quantity) || 0), 0);

    // Fonction pour vider le panier
    const clearCart = () => {
        setCartItems([]);
    };

    return (
        <div className={`header ${theme ? 'dark-mode' : ''}`}>
            <img src={Logo} alt="Logo" className="logo" />
            <ul className="nav-links">
                <li><Link to="/">Accueil</Link></li>
                <li><Link to="/preferences">Préférences</Link></li>
                <li><Link to="/login">Connexion</Link></li>
                <li><Link to="/orders">Mes commandes</Link></li>
                <li><Link to="/complaints">Mes réclamations</Link></li>
                <li><Link to="/contact">Contact</Link></li>
                <li><Link to="/add-article">Ajout article</Link></li>
                <li><Link to="/admin">Admin</Link></li>
            </ul>

            {/* Zone de l'icône du panier */}
            <div className="cart-icon-wrapper">
                {/* Au clic, on inverse l'état d'ouverture du panier */}
                <div className="cart-icon" onClick={() => setIsCartOpen(!isCartOpen)}>
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                        <circle cx="9" cy="21" r="1"></circle>
                        <circle cx="20" cy="21" r="1"></circle>
                        <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"></path>
                    </svg>
                    {totalQuantity > 0 && (
                        <span className="cart-badge">{totalQuantity}</span>
                    )}
                </div>
            </div>

            {/* OVERLAY : Fond sombre cliquable pour fermer le volet */}
            <div 
                className={`cart-overlay ${isCartOpen ? 'open' : ''}`} 
                onClick={() => setIsCartOpen(false)}
            ></div>

            {/* VOLET LATÉRAL (Le fameux encadré bleu de ta capture) */}
            <div className={`cart-drawer ${isCartOpen ? 'open' : ''}`}>
                <div className="cart-drawer-header">
                    <h2>Cart</h2>
                    <button className="close-drawer-btn" onClick={() => setIsCartOpen(false)}>✕</button>
                </div>

                <div className="cart-drawer-items">
                    {cartItems.length === 0 ? (
                        <p className="cart-empty-msg">Votre panier est vide.</p>
                    ) : (
                        cartItems.map((item, index) => (
                            <div className="drawer-item" key={index}>
                                <div className="drawer-item-details">
                                    <span className="drawer-item-name">{item.name}</span>
                                    <div className="drawer-item-bottom">
                                        <span className="drawer-item-price">{Number(item.price).toFixed(2)}€</span>
                                        <span className="drawer-item-qty">QTE : {item.quantity}</span>
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>

                {/* Pied de page du volet avec le total et les boutons */}
                <div className="cart-drawer-footer">
                    <div className="cart-drawer-total">
                        <span>Total:</span>
                        <span>{totalPrice.toFixed(2)}€</span>
                    </div>
                    
                    <div className="cart-drawer-buttons">
                        <button className="btn-drawer btn-clear" onClick={clearCart}>
                            Vider le panier
                        </button>
                        <button className="btn-drawer btn-view" onClick={() => {
                            setIsCartOpen(false); // On ferme le volet avant de naviguer
                            history.push('/cart');
                        }}>
                            Voir mon panier
                        </button>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default Header;
